label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, NE);
label("$E$", E, S);
label("$F$", F, dir(0));
label("$8$", (A + B + E)/3);
label("$5$", (A + D + F)/3);
label("$9$", (C + E + F)/3);

label("$u$", (B + E)/2, S);
label("$v$", (C + E)/2, S);
label("$x$", (C + F)/2, dir(0));
